  caneca: { r: .32, h: .9, masa: 7, rebote: .2, roce: 3.2, col: '#2e7d32', col2: '#1b4d20' },
  caja: { r: .33, h: .6, masa: 4, rebote: .25, roce: 3.6, col: '#b07a43', col2: '#7a5129' },
  valla: { r: .55, h: 1, masa: 14, rebote: .15, roce: 4.5, col: '#e8e8e8', col2: '#d62828' }
