    if (!m) { const m2 = t.match(new RegExp('^' + num)); if (!m2) return null; return { tipo, num: m2[1] + (m2[2] || '').toUpperCase(), sur: m2[5] === 'sur', este: m2[5] === 'este', cruce: null, metros: null, complemento: '' }; }
